<?php
declare(strict_types=1);
require_once __DIR__ . '/Database.php';
$secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Lax']);
session_start();
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function csrf(): string { return '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">'; }
function verifyCsrf(): void { if (!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??''))) { http_response_code(403); exit('Formulario vencido. Recarga la página.'); } }
function goHome(): never { header('Location: /'); exit; }
$error=''; $message=''; $action=(string)($_POST['accion']??''); $pdo=null;

if (isset($_GET['salir'])) {
    try { $db=Database::getInstance('app'); if (!empty($_SESSION['token'])) { $q=$db->prepare('SELECT cerrar_sesion(?)'); $q->execute([$_SESSION['token']]); } } catch(Throwable $ignored) {}
    $_SESSION=[]; session_regenerate_id(true); goHome();
}
try {
    if ($_SERVER['REQUEST_METHOD']==='POST') verifyCsrf();
    if (empty($_SESSION['user_id'])) {
        $pdo=Database::getInstance('app');
        if ($action==='login') {
            $q=$pdo->prepare('SELECT id_usuario,rol,nombre,session_token FROM autenticar_usuario(?,?)');
            $q->execute([trim((string)($_POST['username']??'')),(string)($_POST['password']??'')]);
            $u=$q->fetch(); if (!$u) throw new RuntimeException('Usuario o contraseña incorrectos.');
            session_regenerate_id(true);
            $_SESSION['user_id']=(int)$u['id_usuario']; $_SESSION['role']=$u['rol']; $_SESSION['name']=$u['nombre']; $_SESSION['token']=$u['session_token']; $_SESSION['csrf']=bin2hex(random_bytes(32)); goHome();
        }
        if ($action==='register') {
            $username=trim((string)($_POST['username']??'')); $password=(string)($_POST['password']??''); $confirm=(string)($_POST['password_confirm']??'');
            $doc=trim((string)($_POST['num_doc']??'')); $type=(int)($_POST['id_tipo_doc']??0); $income=filter_var($_POST['ingreso_mensual']??null,FILTER_VALIDATE_FLOAT);
            if (!preg_match('/^[A-Za-z0-9_.-]{4,80}$/',$username)) throw new RuntimeException('El usuario debe tener entre 4 y 80 caracteres.');
            if (strlen($password)<10 || $password!==$confirm) throw new RuntimeException('La contraseña debe tener al menos 10 caracteres y coincidir.');
            if (!$type || !$doc || $income===false || $income<0) throw new RuntimeException('Completa documento e ingreso mensual válido.');
            $q=$pdo->prepare('SELECT sigla FROM tipo_documento WHERE id_tipo_doc=?'); $q->execute([$type]); $sigla=(string)$q->fetchColumn();
            $pattern=in_array($sigla,['CC','TI','RC'],true)?'/^[0-9]{1,10}$/':'/^[A-Za-z0-9]{1,20}$/';
            if (!$sigla || !preg_match($pattern,$doc)) throw new RuntimeException('El documento no coincide con el tipo seleccionado.');
            foreach(['nombre1','apellido1'] as $f) if (!preg_match('/^[\p{L}\p{M} .\'-]+$/u',trim((string)($_POST[$f]??'')))) throw new RuntimeException('Escribe nombres y apellidos válidos.');
            $birth=(string)($_POST['fecha_nacimiento']??''); $date=DateTimeImmutable::createFromFormat('!Y-m-d',$birth);
            if (!$date || $date->format('Y-m-d')!==$birth || $birth>date('Y-m-d')) throw new RuntimeException('Fecha de nacimiento inválida.');
            $q=$pdo->prepare('SELECT registrar_paciente(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
            $q->execute([$username,$password,$type,$doc,trim((string)$_POST['nombre1']),trim((string)($_POST['nombre2']??'')),trim((string)$_POST['apellido1']),trim((string)($_POST['apellido2']??'')),trim((string)($_POST['sexo']??''))?:null,$birth,trim((string)($_POST['telefono']??''))?:null,trim((string)($_POST['correo']??''))?:null,trim((string)($_POST['direccion']??''))?:null,$income]);
            $message='Solicitud registrada. La afiliación quedará pendiente hasta que la EPS verifique el pago externo.';
        }
    } else {
        $role=(string)$_SESSION['role']; $scope=$role==='administrador'?'admin':'app'; $pdo=Database::getInstance($scope);
        Database::setApplicationContext($pdo,(string)($_SESSION['token']??''),$role);
        if ($_SERVER['REQUEST_METHOD']==='POST') {
            if ($role==='paciente' && $action==='reservar') {
                $q=$pdo->prepare('SELECT reservar_cita(?,?)'); $q->execute([(int)($_POST['id_horario']??0),(int)($_POST['id_servicio']??0)]); $message='Cita reservada.';
            } elseif ($role==='medico' && $action==='resultado') {
                $q=$pdo->prepare('SELECT guardar_resultado_cita(?,?)'); $q->execute([(int)($_POST['id_cita']??0),trim((string)($_POST['resultado']??''))]); $message='Resultado guardado.';
            } elseif ($role==='administrador' && $action==='afiliacion') {
                $q=$pdo->prepare('SELECT aprobar_afiliacion(?,?,?)'); $tarifa=($_POST['id_tarifa']??'')===''?null:(int)$_POST['id_tarifa'];
                $q->execute([(int)($_POST['id_paciente']??0),(string)($_POST['estado']??''),$tarifa]); $message='Afiliación actualizada.';
            } elseif ($role==='administrador' && $action==='crear_medico') {
                $username=trim((string)($_POST['username']??'')); $password=(string)($_POST['password']??'');
                if (!preg_match('/^[A-Za-z0-9_.-]{4,80}$/',$username) || strlen($password)<10) throw new RuntimeException('Usuario inválido o contraseña menor de 10 caracteres.');
                $pdo->beginTransaction();
                try {
                    $q=$pdo->prepare("SELECT id_rol FROM roles WHERE codigo='medico'"); $q->execute(); $rid=(int)$q->fetchColumn();
                    $q=$pdo->prepare("INSERT INTO usuarios(username,password_hash,id_rol) VALUES(lower(?),crypt(?,gen_salt('bf')),?) RETURNING id_usuario"); $q->execute([$username,$password,$rid]); $uid=(int)$q->fetchColumn();
                    $q=$pdo->prepare('INSERT INTO medicos(id_usuario,id_tipo_doc,num_doc,nombre1,nombre2,apellido1,apellido2,correo,telefono,id_especialidad,id_consultorio) VALUES(?,?,?,?,?,?,?,?,?,?,?)');
                    $q->execute([$uid,(int)$_POST['id_tipo_doc'],trim((string)$_POST['num_doc']),trim((string)$_POST['nombre1']),trim((string)($_POST['nombre2']??''))?:null,trim((string)$_POST['apellido1']),trim((string)($_POST['apellido2']??''))?:null,trim((string)($_POST['correo']??''))?:null,trim((string)($_POST['telefono']??''))?:null,(int)$_POST['id_especialidad'],($_POST['id_consultorio']??'')===''?null:(int)$_POST['id_consultorio']]);
                    $pdo->commit(); $message='Cuenta médica creada.';
                } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); throw $e; }
            } elseif ($role==='administrador' && $action==='crear_horario') {
                $q=$pdo->prepare("INSERT INTO horario(id_medico,fecha,hora_inicio,hora_fin,id_estado) SELECT ?,?,?,?,id_estado FROM estado WHERE ambito='horario' AND nombre='Disponible'");
                $q->execute([(int)$_POST['id_medico'],(string)$_POST['fecha'],(string)$_POST['hora_inicio'],(string)$_POST['hora_fin']]); $message='Disponibilidad agregada.';
            } elseif ($role==='administrador' && $action==='crear_consultorio') {
                $q=$pdo->prepare("INSERT INTO consultorio(nombre,ubicacion,capacidad,id_estado) SELECT ?,?,?,id_estado FROM estado WHERE ambito='consultorio' AND nombre='Disponible'");
                $q->execute([trim((string)$_POST['nombre']),trim((string)$_POST['ubicacion']),(int)$_POST['capacidad']]); $message='Consultorio creado.';
            } else { http_response_code(403); throw new RuntimeException('Tu perfil no tiene permiso para esa operación.'); }
        }
    }
} catch(Throwable $e) {
    if (!$pdo) { http_response_code(503); $error='No se pudo conectar con PostgreSQL. Revisa la configuración de la base de datos.'; }
    else $error=$e instanceof PDOException?'No se pudo guardar la operación. Revisa los datos, duplicados o permisos.':$e->getMessage();
}

if (empty($_SESSION['user_id'])) {
    $pdo=Database::getInstance('app'); $types=$pdo->query('SELECT id_tipo_doc,sigla,nombre FROM tipo_documento ORDER BY sigla')->fetchAll();
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EPS Villavicencio | Ingreso</title><link rel="stylesheet" href="/assets/app.css"></head><body class="auth-page"><header class="site-header"><a class="brand" href="/"><span class="brand-symbol">+</span><span><strong>EPS Villavicencio</strong><small>Portal de servicios en salud</small></span></a><span>Atención al usuario</span></header><main class="auth-layout"><section class="auth-illustration"><img src="/assets/ilustracion-familia.png" alt="Ilustración de una familia"><div><p class="eyebrow">Cerca de ti</p><h1>Tu bienestar, nuestra prioridad.</h1><p>Consulta tus citas y accede a los servicios de salud desde un solo lugar.</p></div></section><section class="auth-panel"><p class="eyebrow">Portal de afiliados</p><h2>Bienvenido</h2><p>Ingresa a tu cuenta o registra una solicitud de afiliación.</p><?php if($message):?><div class="notice"><?=h($message)?></div><?php endif?><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?><div class="tabs"><button type="button" class="tab active" data-tab="login">Iniciar sesión</button><button type="button" class="tab" data-tab="register">Crear cuenta</button></div><form method="post" class="auth-form tab-panel active" data-panel="login"><input type="hidden" name="accion" value="login"><?=csrf()?><label>Usuario</label><input name="username" required autocomplete="username"><label>Contraseña</label><input name="password" type="password" required autocomplete="current-password"><button class="button primary">Ingresar</button></form><form method="post" class="auth-form tab-panel" data-panel="register"><input type="hidden" name="accion" value="register"><?=csrf()?><div class="form-grid"><div class="field full"><label>Usuario</label><input name="username" minlength="4" required></div><div class="field"><label>Contraseña (mínimo 10 caracteres)</label><input name="password" type="password" minlength="10" required></div><div class="field"><label>Confirmar contraseña</label><input name="password_confirm" type="password" minlength="10" required></div><div class="field"><label>Tipo de documento</label><select name="id_tipo_doc" required><?php foreach($types as $t):?><option value="<?=h($t['id_tipo_doc'])?>"><?=h($t['sigla'].' · '.$t['nombre'])?></option><?php endforeach?></select></div><div class="field"><label>Número de documento</label><input name="num_doc" maxlength="20" required></div><div class="field"><label>Primer nombre</label><input name="nombre1" required></div><div class="field"><label>Segundo nombre</label><input name="nombre2"></div><div class="field"><label>Primer apellido</label><input name="apellido1" required></div><div class="field"><label>Segundo apellido</label><input name="apellido2"></div><div class="field"><label>Fecha de nacimiento</label><input name="fecha_nacimiento" type="date" max="<?=date('Y-m-d')?>" required></div><div class="field"><label>Ingreso mensual</label><input name="ingreso_mensual" type="number" min="0" step="1000" required></div><div class="field"><label>Teléfono</label><input name="telefono"></div><div class="field"><label>Correo</label><input name="correo" type="email"></div><div class="field full"><label>Dirección</label><input name="direccion"></div></div><button class="button primary">Enviar solicitud</button><p class="form-footnote">La EPS verificará el pago por sus canales externos.</p></form><footer>EPS Villavicencio · Portal académico</footer></section></main><script>document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===b.dataset.tab));}));<?php if($action==='register'):?>document.querySelector('[data-tab="register"]').click();<?php endif?></script></body></html><?php exit;
}

