?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EPS Villavicencio | Portal</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="app-header"><a class="brand" href="/"><span class="brand-symbol">+</span><span><strong>EPS Villavicencio</strong><small>Gestión de citas médicas</small></span></a><div><?=h($name)?> · <?=h(ucfirst($role))?> <a class="button secondary compact" href="/?salir=1">Cerrar sesión</a></div></header><main class="container"><p class="eyebrow"><?=h(strtoupper($role))?></p><h1><?= $role==='paciente'?'Mi portal':($role==='medico'?'Mi agenda':'Administración') ?></h1><?php if($message):?><div class="notice"><?=h($message)?></div><?php endif?><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?>
