 $q=$pdo->query('SELECT id_paciente,estado_afiliacion FROM pacientes WHERE id_usuario=app_user_id()'); $patient=$q->fetch();
 $slots=$pdo->query('SELECT id_horario,fecha,hora_inicio,hora_fin,medico,especialidad FROM horarios_disponibles ORDER BY fecha,hora_inicio')->fetchAll();
 $services=$pdo->query('SELECT id_servicio,nombre,costo_base FROM servicio ORDER BY nombre')->fetchAll();
 $appts=$pdo->query("SELECT c.id_cita,c.valor_cobrado,e.nombre AS estado,h.fecha,h.hora_inicio,m.nombre1||' '||m.apellido1 AS medico,s.nombre AS servicio,r.resultado FROM cita c JOIN estado e USING(id_estado) JOIN horario h USING(id_horario) JOIN medicos m USING(id_medico) JOIN servicio s USING(id_servicio) LEFT JOIN resultado_consulta r USING(id_cita) WHERE c.id_paciente=app_paciente_id() ORDER BY h.fecha DESC,h.hora_inicio DESC")->fetchAll();
