 $patients=$pdo->query('SELECT p.id_paciente,p.num_doc,p.nombre1,p.apellido1,p.ingreso_mensual,p.estado_afiliacion,t.sigla FROM pacientes p JOIN tipo_documento t USING(id_tipo_doc) ORDER BY p.apellido1')->fetchAll();
 $tariffs=$pdo->query('SELECT id_tarifa,nombre FROM tarifa ORDER BY id_tarifa')->fetchAll(); $doctors=$pdo->query('SELECT id_medico,nombre1,apellido1 FROM medicos ORDER BY apellido1')->fetchAll(); $clinics=$pdo->query('SELECT id_consultorio,nombre FROM consultorio ORDER BY nombre')->fetchAll();
