undo apellido</label><input name="apellido2"></div><div class="field"><label>Correo</label><input name="correo" type="email"></div><div class="field"><label>Teléfono</label><input name="telefono"></div><div class="field"><label>Especialidad</label><select name="id_especialidad"><?php foreach($specialties as $s):?><option value="<?=h($s['id_especialidad'])?>"><?=h($s['nombre'])?></option><?php endforeach?></select></div><div class="field"><label>Consultorio</label><select name="id_consultorio"><option value="">Sin asignar</option><?php foreach($clinics as $c):?><option value="<?=h($c['id_consultorio'])?>"><?=h($c['nombre'])?></option><?php endforeach?></select></div><div class="field full"><button class="button primary">Crear médico</button></div></form></section><section class="panel"><h2>Configurar disponibilidad</h2><form method="post"><?=csrf()?><input type="hidden" name="accion" value="crear_horario"><label>Médico</label><select name="id_medico" required><?php foreach($doctors as $d):?><option value="<?=h($d['id_medico'])?>"><?=h($d['nombre1'].' '.$d['apellido1'])?></option><?php endforeach?></select><label>Fecha</label><input type="date" name="fecha" min="<?=date('Y-m-d')?>" required><div class="form-grid"><div class="field"><label>Inicio</label><input type="time" name="hora_inicio" required></div><div class="field"><label>Fin</label><input type="time" name="hora_fin" required></div></div><button class="button primary">Agregar horario</button></form><hr><h3>Crear consultorio</h3><form method="post"><?=csrf()?><input type="hidden" name="accion" value="crear_consultorio"><label>Nombre</label><input name="nombre" required><label>Ubicación</label><input name="ubicacion" required><label>Capacidad</label><input name="capacidad" type="number" min="0" required><button class="button secondary">Crear consultorio</button></form></section></div>
